package com.bocsoft.sqleditor.metadata.api;
public class ColumnItem { private final String name,typeName,jdbcType,defaultValue,extra,comment; private final Integer length,precision,scale,ordinal; private final boolean nullable,primaryKey;
    public ColumnItem(String name,String typeName,String jdbcType,Integer length,Integer precision,Integer scale,boolean nullable,String defaultValue,String extra,String comment,Integer ordinal,boolean primaryKey){this.name=name;this.typeName=typeName;this.jdbcType=jdbcType;this.length=length;this.precision=precision;this.scale=scale;this.nullable=nullable;this.defaultValue=defaultValue;this.extra=extra;this.comment=comment;this.ordinal=ordinal;this.primaryKey=primaryKey;}
    public String getName(){return name;} public String getTypeName(){return typeName;} public String getJdbcType(){return jdbcType;} public Integer getLength(){return length;} public Integer getPrecision(){return precision;} public Integer getScale(){return scale;} public boolean isNullable(){return nullable;} public String getDefaultValue(){return defaultValue;} public String getExtra(){return extra;} public String getComment(){return comment;} public Integer getOrdinal(){return ordinal;} public boolean isPrimaryKey(){return primaryKey;}}
